/***
 * MARK: routing
 * @description Single route table for the KainBain SPA (HashRouter-first).
 * The router location is the source of truth for the current view:
 * leaving a view IS a navigation, so a stale docs/task location can never
 * survive it, and refresh re-opens the CURRENT route with its params.
 *
 * Route table (canonical paths; the HashRouter renders them as `#/...` URLs):
 *
 * | View         | Canonical path        | Legacy entries (redirect)        |
 * |--------------|-----------------------|----------------------------------|
 * | Orchestrator | `/`                   | `#/orchestrator`, `?view=...`    |
 * | Files & Repo | `/explorer`           | `?view=explorer`                 |
 * | Settings     | `/settings`           | `?view=settings`                 |
 * | System Settings| `/system-settings/:section?` | (none)                    |
 * | Observability| `/observability`      | `?view=observability`            |
 * | Docs         | `/docs/:slug?`        | `#docs`, `?view=docs`            |
 * | Task detail  | `/tasks/:id`          | `#/task/:id`, `?task=:id`        |
 * | Task review  | `/tasks/:id/review`   | (existing shape, now canonical)  |
 * | Task survey  | `/tasks/:id/survey`   | `#/task/:id/survey` (legacy)       |
 * | Retrospective| `/retrospective`      | (none — new view, no legacy)     |
 * | Accessibility| `/accessibility`      | `?view=accessibility`            |
 *
 * Note: `/settings` is project-scoped (ProjectSettings); `/system-settings` is
 * application-level (SystemSettingsPage, a full screen — not a modal). The
 * System Menu entry and the `S` shortcut open it in a new window by default
 * (`openSystemSettings`), falling back to same-tab `setView('system-settings')`
 * when the popout is blocked or the viewport is phone-narrow. The `:section`
 * segment (or `?section=`) deep-links a settings tab.
 *
 * Refresh guarantees:
 * - Refresh re-opens the CURRENT route (docs slug, task id preserved).
 * - Unknown locations keep the current view (explicit catch-all, no switch).
 * - Each view entry is one history entry; back/forward traverse real entries.
 * - Legacy-redirect normalisation uses history REPLACE, never a push.
 *
 * How to add a view: add its canonical path here + a `<Route>` in
 * `routes.jsx` + a `viewToPath`/`routeToView` row + redirect/tests below.
 * A future move to `<BrowserRouter>` is mechanical: canonical paths are
 * already full-URL shaped; only the router shell in `main.jsx` changes.
 ***/

export const ROUTES = {
  orchestrator: '/',
  explorer: '/explorer',
  settings: '/settings',
  systemSettings: '/system-settings',
  systemSettingsSection: '/system-settings/:section',
  observability: '/observability',
  docs: '/docs',
  docsArticle: '/docs/:slug',
  taskDetail: '/tasks/:id',
  taskReview: '/tasks/:id/review',
  taskSurvey: '/tasks/:id/survey',
  retrospective: '/retrospective',
  accessibility: '/accessibility',
};

/***
 * MARK: viewToPath
 * @description Canonical router path for a view id. The `setView` facade
 *   navigates here, so every view entry writes exactly one history entry.
 * @param {string} view - View id (`orchestrator`, `explorer`, `settings`,
 *   `system-settings`, `observability`, `docs`, `task-detail`/`task`,
 *   `task-review`, `tasks`, `retrospective`, `accessibility`).
 * @param {Object} [opts]
 * @param {string} [opts.taskId] - Task id for task-detail/task-review paths.
 * @param {string} [opts.slug] - Docs slug for the docs article path.
 * @param {string} [opts.section] - Settings tab id for the system-settings path.
 * @returns {string|null} Canonical path, or null for unknown views.
 * @example viewToPath('docs', { slug: 'architecture' }) => '/docs/architecture'
 ***/
export function viewToPath(view, opts = {}) {
  const { taskId, slug, section } = opts;
  switch (view) {
    case 'orchestrator':
    case 'tasks':
      return '/';
    case 'explorer':
      return '/explorer';
    case 'settings':
      return '/settings';
    case 'system-settings':
      return section ? `/system-settings/${encodeURIComponent(section)}` : '/system-settings';
    case 'observability':
      return '/observability';
    case 'docs':
      return slug ? `/docs/${encodeURIComponent(slug)}` : '/docs';
    case 'task-detail':
    case 'task':
      return taskId ? `/tasks/${encodeURIComponent(taskId)}` : '/';
    case 'task-review':
      return taskId ? `/tasks/${encodeURIComponent(taskId)}/review` : '/';
    case 'task-survey':
      return taskId ? `/tasks/${encodeURIComponent(taskId)}/survey` : '/';
    case 'retrospective':
      return '/retrospective';
    case 'accessibility':
      return '/accessibility';
    default:
      return null;
  }
}

/***
 * MARK: routeToView
 * @description Resolves a router pathname to its view + params.
 *   Returns null for unknown paths so the caller keeps the current view
 *   instead of switching on fragments like `/main-content`.
 * @param {string} pathname - Router pathname (e.g. `/docs/architecture`).
 * @returns {{ view: string, taskId?: string, slug?: string, section?: string }|null}
 * @example routeToView('/tasks/t1/review') => { view: 'task-review', taskId: 't1' }
 * @example routeToView('/system-settings/models') => { view: 'system-settings', section: 'models' }
 ***/
export function routeToView(pathname) {
  if (typeof pathname !== 'string') return null;
  const path = pathname.length > 1 ? pathname.replace(/\/+$/, '') : pathname;
  if (path === '/' || path === '/orchestrator') return { view: 'orchestrator' };
  if (path === '/explorer') return { view: 'explorer' };
  if (path === '/settings') return { view: 'settings' };
  if (path === '/system-settings') return { view: 'system-settings' };
  const systemSettingsMatch = path.match(/^\/system-settings\/([^/]+)$/);
  if (systemSettingsMatch) {
    return { view: 'system-settings', section: safeDecode(systemSettingsMatch[1]) };
  }
  if (path === '/observability') return { view: 'observability' };
  if (path === '/retrospective') return { view: 'retrospective' };
  if (path === '/accessibility') return { view: 'accessibility' };
  if (path === '/docs') return { view: 'docs' };
  const docsMatch = path.match(/^\/docs\/([^/]+)$/);
  if (docsMatch) return { view: 'docs', slug: safeDecode(docsMatch[1]) };
  const reviewMatch = path.match(/^\/(?:tasks|task)\/([^/]+)\/review$/);
  if (reviewMatch) return { view: 'task-review', taskId: safeDecode(reviewMatch[1]) };
  const surveyMatch = path.match(/^\/(?:tasks|task)\/([^/]+)\/survey$/);
  if (surveyMatch) return { view: 'task-survey', taskId: safeDecode(surveyMatch[1]) };
  // Legacy singular shape (`#/task/:id`) — canonicalises to `/tasks/:id`.
  const detailMatch = path.match(/^\/(?:tasks|task)\/([^/]+)$/);
  if (detailMatch) return { view: 'task-detail', taskId: safeDecode(detailMatch[1]) };
  return null;
}

function safeDecode(segment) {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}

const LEGACY_VIEW_PATHS = {
  orchestrator: '/',
  tasks: '/',
  explorer: '/explorer',
  settings: '/settings',
  'system-settings': '/system-settings',
  observability: '/observability',
  docs: '/docs',
  accessibility: '/accessibility',
};

/***
 * MARK: normalizeLegacyUrl
 * @description Maps legacy entry URLs onto their canonical hash ONCE at boot
 *   (via `history.replaceState`, so no extra history entry is created).
 *   Returns null when the URL is already canonical and must be left alone.
 * @param {{ hash?: string, search?: string, pathname?: string }} loc
 *   A `window.location`-like. Defaults to the live location.
 * @returns {string|null} Canonical hash (e.g. `#/docs/architecture`) or null.
 * @example normalizeLegacyUrl({ hash: '#docs', search: '', pathname: '/' }) => '#/docs'
 ***/
export function normalizeLegacyUrl(loc = defaultLocation()) {
  const hash = loc?.hash || '';
  const search = loc?.search || '';
  const pathname = loc?.pathname || '';

  // Legacy query entries (`?view=`, `?task=`) win, matching the old boot order.
  if (search) {
    try {
      const params = new URLSearchParams(search);
      const queryView = params.get('view');
      const queryTask = params.get('task');
      const wantsReview = queryView === 'task-review' || hash.includes('/review');
      const wantsSurvey = queryView === 'task-survey' || hash.includes('/survey');
      if (queryTask && (queryView === 'task-review' || queryView === 'task-survey' || !queryView)) {
        if (wantsSurvey) return `#/tasks/${encodeURIComponent(queryTask)}/survey`;
        return wantsReview
          ? `#/tasks/${encodeURIComponent(queryTask)}/review`
          : `#/tasks/${encodeURIComponent(queryTask)}`;
      }
      if (queryView && LEGACY_VIEW_PATHS[queryView] !== undefined) {
        if ((queryView === 'task' || queryView === 'task-review') && queryTask) {
          return queryView === 'task-review'
            ? `#/tasks/${encodeURIComponent(queryTask)}/review`
            : `#/tasks/${encodeURIComponent(queryTask)}`;
        }
        if (queryView === 'task' || queryView === 'task-review' || queryView === 'tasks') {
          return '#/';
        }
        return `#${LEGACY_VIEW_PATHS[queryView] === '/' ? '/' : LEGACY_VIEW_PATHS[queryView]}`;
      }
    } catch {
      // fall through to hash/path handling
    }
  }

  if (hash === '#docs') return '#/docs';
  if (hash === '#/orchestrator') return '#/';
  const singularTask = hash.match(/^#\/task\/([^?#/]+)(\/review|\/survey)?\/?$/);
  if (singularTask) {
    const id = singularTask[1];
    if (singularTask[2] === '/review') return `#/tasks/${id}/review`;
    if (singularTask[2] === '/survey') return `#/tasks/${id}/survey`;
    return `#/tasks/${id}`;
  }
  // A present hash is either already canonical (`#/...`) or an in-page
  // fragment (`#main-content`): both must be left alone.
  if (hash) return null;

  // Server-style paths (no hash yet): only mapped when they name a real view.
  if (!pathname || pathname === '/') return null;
  const asRoute = routeToView(pathname);
  if (asRoute) {
    if (asRoute.view === 'orchestrator') return '#/';
    if (asRoute.view === 'docs') return asRoute.slug ? `#/docs/${asRoute.slug}` : '#/docs';
    if (asRoute.view === 'task-detail') return `#/tasks/${asRoute.taskId}`;
    if (asRoute.view === 'task-review') return `#/tasks/${asRoute.taskId}/review`;
    if (asRoute.view === 'task-survey') return `#/tasks/${asRoute.taskId}/survey`;
    if (asRoute.view === 'system-settings') {
      return `#${viewToPath('system-settings', { section: asRoute.section })}`;
    }
    return `#${viewToPath(asRoute.view)}`;
  }
  return null;
}

function defaultLocation() {
  if (typeof window !== 'undefined' && window.location) return window.location;
  return { hash: '', search: '', pathname: '/' };
}

import React, { useEffect, useState } from 'react';
import { api } from '../../services/api';
import { logger } from '../../services/logger';
import { GlossaryTerm } from '../common/GlossaryTerm';
import {
  AAA_STATUS_LABELS,
  READINESS_LABELS,
  loadStatementResults,
} from '../../a11y/statementResults';
import { AccessibilityReportDialog } from './AccessibilityReportDialog';

// Container-token chip per status (every pair holds 7:1 — see
// theme/containerContrast.test.js). The text label always carries the
// meaning, never the colour alone (WCAG 1.4.1).
const CHIP_TONES = {
  supported: 'bg-primary-container text-on-primary-container',
  'partly-supported': 'bg-warning-container text-on-warning-container',
  'not-supported': 'bg-error-container text-on-error-container',
  'not-applicable': 'bg-secondary-container text-on-secondary-container',
  unknown: 'bg-tertiary-container text-on-tertiary-container',
  partial: 'bg-warning-container text-on-warning-container',
};

const StatusChip = ({ prefix, tone, label }) => (
  <span
    className={`inline-flex items-center gap-1.5 px-3 py-1.5 min-h-[44px] rounded-sm text-xs font-bold ${CHIP_TONES[tone] || CHIP_TONES.unknown}`}
  >
    <span className="font-mono">{prefix}</span>
    <span>{label}</span>
  </span>
);

const CriterionRow = ({ row }) => (
  <li className="py-2 border-b border-border-standard last:border-b-0">
    <p className="text-sm text-on-surface">
      <strong className="font-bold">
        {row.id} {row.title}
      </strong>{' '}
      <span className="text-text-muted">— {AAA_STATUS_LABELS[row.status]}</span>
    </p>
    <p className="text-sm text-text-muted mt-0.5">{row.plainWords}</p>
    <p className="text-xs text-text-muted mt-0.5 font-mono">
      Checked by: {row.instrument}
      {row.evidence ? ` · ${row.evidence}` : ''}
    </p>
  </li>
);

const OutcomeRow = ({ row }) => (
  <li className="py-2 border-b border-border-standard last:border-b-0">
    <p className="text-sm text-on-surface">
      <strong className="font-bold">{row.plainWords}</strong>{' '}
      <span className="text-text-muted">— {READINESS_LABELS[row.readiness]}</span>
    </p>
    <p className="text-xs text-text-muted mt-0.5 font-mono">
      Assessed from: {row.approximatedBy}
      {row.note ? ` · ${row.note}` : ''}
    </p>
  </li>
);

const NeedGroupSection = ({ entry }) => {
  const checkCount = entry.aaaRows.length + entry.w30Rows.length;
  return (
    <section
      aria-labelledby={`need-group-heading-${entry.group.id}`}
      data-testid={`need-group-${entry.group.id}`}
      className="border border-border-standard rounded-sm bg-surface-container-low p-4"
    >
      <h2
        id={`need-group-heading-${entry.group.id}`}
        className="text-lg font-bold text-on-surface"
      >
        {entry.group.label}
      </h2>
      <p className="text-sm text-text-muted mt-1">{entry.group.blurb}</p>
      <div className="flex flex-wrap gap-2 mt-3">
        <StatusChip prefix="AAA" tone={entry.aaaStatus} label={entry.aaaLabel} />
        <StatusChip prefix="3.0" tone={entry.w30Readiness} label={entry.w30Label} />
      </div>
      {entry.knownIssues.length > 0 && (
        <div className="mt-3">
          <h3 className="text-sm font-bold text-on-surface">Known issues in this area</h3>
          <ul className="list-disc pl-5 mt-1 space-y-1">
            {entry.knownIssues.map((issue) => (
              <li key={issue.id} className="text-sm text-text-muted">
                {issue.summary}
              </li>
            ))}
          </ul>
        </div>
      )}
      <details className="mt-3 border border-border-standard rounded-sm bg-surface-container">
        <summary className="min-h-[44px] flex items-center px-3 py-2 text-sm font-bold text-on-surface cursor-pointer">
          Show the {checkCount} checks behind this group
        </summary>
        <div className="px-3 pb-3">
          <h3 className="text-sm font-bold text-on-surface mt-1">AAA checks</h3>
          <ul>
            {entry.aaaRows.map((row) => (
              <CriterionRow key={row.id} row={row} />
            ))}
          </ul>
          <h3 className="text-sm font-bold text-on-surface mt-3">
            WCAG 3.0 draft readiness (not a certificate)
          </h3>
          <ul>
            {entry.w30Rows.map((row) => (
              <OutcomeRow key={row.id} row={row} />
            ))}
          </ul>
        </div>
      </details>
    </section>
  );
};

const formatCheckedDate = (isoValue) => {
  if (typeof isoValue !== 'string' || isoValue === '') return 'date unknown';
  const parsed = new Date(isoValue);
  if (Number.isNaN(parsed.getTime())) return 'date unknown';
  return new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium' }).format(parsed);
};

/***
 * MARK: AccessibilityStatementPage
 * @description Dynamic accessibility statement (`/accessibility`): grouped
 *   by the five user needs (not by report structure), with each group
 *   showing its WCAG 2.2 AAA status and its WCAG 3.0 draft-readiness side
 *   by side. Statuses derive from the latest stored check results fetched
 *   at runtime (with a visible last-checked date); a curated fallback
 *   renders only when no results can be loaded. A report-a-problem call to
 *   action opens above the statement and repeats at the end. Document title
 *   stays owned by App.jsx; this view never sets it.
 * @example <AccessibilityStatementPage />
 ***/
export function AccessibilityStatementPage() {
  const [data, setData] = useState(null);
  const [reportOpen, setReportOpen] = useState(false);

  useEffect(() => {
    let alive = true;
    const load = async () => {
      const result = await loadStatementResults(api.accessibilityResults);
      if (!alive) return;
      if (!result.isFallback && result.warnings.length > 0) {
        logger.warn('Accessibility results carried warnings:', result.warnings);
      }
      setData(result);
    };
    void load();
    return () => {
      alive = false;
    };
  }, []);

  const checkedDate = data ? formatCheckedDate(data.artifact.generatedAt) : 'date unknown';
  const appVersion = data?.artifact.appVersion || 'unknown';
  const contactEmail = data?.artifact.contactEmail || '';

  // Page scroll owner (`flex-1 min-h-0 overflow-y-auto`, matching the
  // TaskDetailPage / DocsView contract). A plain <div>, NOT a second
  // <main>: the shell already owns the single top-level main landmark.
  return (
    <div data-testid="accessibility-page" className="flex-1 min-h-0 overflow-y-auto custom-scrollbar">
      <div className="flex flex-col gap-4 p-4 max-w-4xl mx-auto w-full">
        <header className="flex flex-col gap-2">
          <h1 className="text-xl font-bold text-on-surface">Accessibility statement</h1>
          <p className="text-sm text-text-muted">
            We want everyone to be able to use KainBain. This statement explains how accessible
            the app is today, grouped by what you need to do rather than by the checklists we
            run. It covers{' '}
            <GlossaryTerm
              term="WCAG"
              expansion="Web Content Accessibility Guidelines"
              definition="The shared standard for accessible web content, published by the W3C."
            />{' '}
            2.2 level{' '}
            <GlossaryTerm
              term="AAA"
              expansion="Triple-A"
              definition="The highest WCAG conformance level, above A and AA."
            />{' '}
            checks and our readiness for the WCAG 3.0 draft. WCAG 3.0 is still a draft, so its
            readiness is our own assessment, never a certificate.
          </p>
          <p role="status" className="text-sm text-text-muted" data-testid="statement-freshness">
            {!data && 'Loading the latest accessibility results…'}
            {data &&
              !data.isFallback &&
              `Results last checked ${checkedDate} · App version ${appVersion}.`}
            {data &&
              data.isFallback &&
              `Showing the last-known statement from ${checkedDate} because the latest results could not be loaded · App version ${appVersion}.`}
          </p>
          <div>
            <button
              type="button"
              onClick={() => setReportOpen(true)}
              className="px-4 py-2 min-h-[44px] bg-primary text-on-primary text-xs font-bold uppercase tracking-widest rounded-sm hover:brightness-110 transition-all cursor-pointer"
            >
              Report an accessibility problem
            </button>
            <p className="text-xs text-text-muted mt-1">
              For any barrier you hit, whether or not it appears in a standard.
            </p>
          </div>
        </header>

        {data?.groups.map((entry) => <NeedGroupSection key={entry.group.id} entry={entry} />)}

        <section
          aria-labelledby="statement-commitment-heading"
          className="border border-border-standard rounded-sm bg-surface-container-low p-4"
        >
          <h2 id="statement-commitment-heading" className="text-lg font-bold text-on-surface">
            Our commitment and how to contact us
          </h2>
          <p className="text-sm text-text-muted mt-2">
            We are committed to making KainBain usable by people with disabilities, and we treat
            accessibility problems as defects. This statement covers the whole app: the
            orchestrator board, files and repository, project settings, the observability
            monitor, docs, task detail, review, and survey pages, the retrospective, and this
            statement itself.
          </p>
          <p className="text-sm text-text-muted mt-2">
            The app aims for WCAG 2.2 level AA conformance everywhere, and level AAA except for
            the known issues listed above. If you find a barrier — in a standard or not — please
            report it using the button on this page
            {contactEmail && (
              <>
                {' '}
                or by emailing the website team at{' '}
                <a
                  href={`mailto:${contactEmail}`}
                  className="underline underline-offset-2 hover:text-on-surface"
                >
                  {contactEmail}
                </a>
              </>
            )}
            . We reply to every report.
          </p>
        </section>

        <section
          aria-labelledby="statement-checks-heading"
          className="border border-border-standard rounded-sm bg-surface-container-low p-4"
        >
          <h2 id="statement-checks-heading" className="text-lg font-bold text-on-surface">
            How we check accessibility
          </h2>
          <p className="text-sm text-text-muted mt-2">
            Every change runs automated scans at the AAA level plus a text-contrast walk, unit
            gates for focus, targets, and wording, and manual keyboard and screen-reader passes.
            The app works in current browsers with JavaScript and needs no plug-ins. This
            statement was last checked on {checkedDate} and is reviewed with each release.
          </p>
          <div className="mt-3">
            <button
              type="button"
              onClick={() => setReportOpen(true)}
              className="px-4 py-2 min-h-[44px] bg-primary text-on-primary text-xs font-bold uppercase tracking-widest rounded-sm hover:brightness-110 transition-all cursor-pointer"
            >
              Report an accessibility problem
            </button>
          </div>
        </section>

        {reportOpen && (
          <AccessibilityReportDialog
            contactEmail={contactEmail}
            onClose={() => setReportOpen(false)}
          />
        )}
      </div>
    </div>
  );
}

/***
 * MARK: AccessibilityStatementPage default export
 * @description Default export mirroring the named component export.
 * @example import AccessibilityStatementPage from './AccessibilityStatementPage';
 ***/
export default AccessibilityStatementPage;

import React, { useEffect, useRef, useState } from 'react';
import { api } from '../../services/api';
import { Modal } from '../Modal';
import { usePendingAction } from '../../hooks/usePendingAction';
import { NEED_GROUPS } from '../../a11y/statementResults';

const MESSAGE_MAX_CHARS = 4000;
const CONTACT_MAX_CHARS = 320;
const PAGE_URL_MAX_CHARS = 2048;

const initialFieldErrors = () => ({});

/***
 * MARK: AccessibilityReportDialog
 * @description Short on-site form for reporting an accessibility problem —
 *   explicitly for any barrier, whether or not a standard covers it. Visible
 *   labels, named errors with fix suggestions, a single-flight submit guard,
 *   and a confirmation state (reusing the FeedbackDialog modal patterns).
 *   Server-side fixes ride back onto the same fields when the endpoint
 *   rejects the report; a mailto fallback appears when the endpoint is
 *   unreachable and the team inbox is configured.
 * @example <AccessibilityReportDialog contactEmail="team@example.com" onClose={() => setOpen(false)} />
 ***/
export function AccessibilityReportDialog({ contactEmail = '', onClose }) {
  const { pendingKey, run } = usePendingAction();
  const isSubmitting = pendingKey === 'submit';

  const [message, setMessage] = useState('');
  const [needGroup, setNeedGroup] = useState('');
  const [contact, setContact] = useState('');
  const [pageUrl, setPageUrl] = useState(
    () => (typeof window !== 'undefined' ? window.location.hash || '' : ''),
  );
  const [fieldErrors, setFieldErrors] = useState(initialFieldErrors);
  const [submitError, setSubmitError] = useState(null);
  const [submitted, setSubmitted] = useState(null);
  const confirmationRef = useRef(null);

  useEffect(() => {
    if (submitted) confirmationRef.current?.focus?.();
  }, [submitted]);

  const validate = () => {
    const errors = {};
    const trimmed = message.trim();
    if (trimmed === '') {
      errors.message = {
        message: 'Describe the problem you hit.',
        fix: 'Write a sentence or two about what happened — for example, which page and what got in your way.',
      };
    } else if (trimmed.length > MESSAGE_MAX_CHARS) {
      errors.message = {
        message: `Keep the description under ${MESSAGE_MAX_CHARS} characters (yours is ${trimmed.length}).`,
        fix: 'Shorten the description to the key details: the page, the barrier, and what you were trying to do.',
      };
    }
    if (contact.trim() !== '' && contact.trim().length > CONTACT_MAX_CHARS) {
      errors.contact = {
        message: `Keep contact details under ${CONTACT_MAX_CHARS} characters.`,
        fix: 'Shorten the contact details to just an email address or phone number.',
      };
    }
    if (pageUrl.trim() !== '' && pageUrl.trim().length > PAGE_URL_MAX_CHARS) {
      errors.pageUrl = {
        message: `Keep the page address under ${PAGE_URL_MAX_CHARS} characters.`,
        fix: 'Shorten the page address to just the page path.',
      };
    }
    return errors;
  };

  const applyServerErrors = (thrown) => {
    try {
      const payload = JSON.parse(thrown?.body || '');
      if (Array.isArray(payload?.errors) && payload.errors.length > 0) {
        const mapped = {};
        for (const entry of payload.errors) {
          if (entry && typeof entry.field === 'string' && typeof entry.message === 'string') {
            mapped[entry.field] = { message: entry.message, fix: entry.fix || '' };
          }
        }
        if (Object.keys(mapped).length > 0) {
          setFieldErrors(mapped);
          return true;
        }
      }
    } catch {
      // Not a structured error body — fall through to the generic message.
    }
    return false;
  };

  const handleSubmit = (event) => {
    if (event) event.preventDefault();
    if (pendingKey || submitted) return;
    const errors = validate();
    setFieldErrors(errors);
    setSubmitError(null);
    if (Object.keys(errors).length > 0) return;
    void run('submit', () =>
      api
        .submitAccessibilityFeedback({
          message: message.trim(),
          needGroup: needGroup || null,
          contact: contact.trim() || null,
          pageUrl: pageUrl.trim() || null,
        })
        .then((response) => {
          setSubmitted({ id: response?.id || '' });
        })
        .catch((thrown) => {
          // Structured rejections land on the fields with fix suggestions;
          // anything else keeps the dialog open with the draft intact and
          // offers the email fallback, so reporting never dead-ends.
          if (!applyServerErrors(thrown)) {
            setSubmitError(
              'The report could not be sent. Check your connection and try again — your words are still here.',
            );
          }
        }),
    );
  };

  const handleKeyDown = (event) => {
    if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {
      event.preventDefault();
      handleSubmit();
    }
  };

  const describeIds = (field) => (fieldErrors[field] ? `a11y-report-${field}-error` : undefined);
  const mailtoHref =
    contactEmail.trim() !== ''
